"""Loopback-only team UI preview: real plugin routes, SQLite and graph checkpoints.

Identity and AgentRuns admission are synthetic. This is a browser fixture, not
production authentication or a substitute for Gateway run-control tests.
"""

import asyncio
import sys
from contextlib import asynccontextmanager
from pathlib import Path
from tempfile import TemporaryDirectory
from types import SimpleNamespace

import uvicorn
from deerflow_extension_api import AgentRun, AgentRunError
from deerflow_extension_api.agent_runs import AGENT_RUNS_RESOLVER_KEY
from deerflow_extension_api.auth import EXTENSION_PRINCIPAL_RESOLVER_KEY, ExtensionPrincipal
from deerflow_extension_api.plugins import ToolContext
from fastapi import FastAPI, Request
from fastapi.responses import HTMLResponse
from langchain.agents import create_agent
from langchain_core.language_models.fake_chat_models import FakeMessagesListChatModel
from langchain_core.messages import AIMessage
from langchain_core.outputs import ChatGeneration, ChatResult
from langgraph.checkpoint.memory import InMemorySaver

from app.gateway.routers.plugins import router
from deerflow.agents.middlewares.clarification_middleware import ClarificationMiddleware
from deerflow.extensions.loader import ExtensionSpec, load_extensions
from deerflow.tools.builtins.clarification_tool import ask_clarification_tool


class PreviewModel(FakeMessagesListChatModel):
    def bind_tools(self, tools, **kwargs):
        return self

    def _generate(self, messages, stop=None, run_manager=None, **kwargs):
        latest = next(m for m in reversed(messages) if m.type == "human")
        response = latest.additional_kwargs.get("human_input_response")
        if response:
            answer = AIMessage(content=f"Clarification accepted: {response['value']}.")
        elif "Clarification fixture" in latest.content:
            answer = AIMessage(content="", tool_calls=[{"name": "ask_clarification", "id": "clarify-environment", "args": {"question": "Which environment should I check?", "clarification_type": "missing_info"}, "type": "tool_call"}])
        else:
            answer = AIMessage(content="Release evidence verified. See the shared team record.")
        return ChatResult(generations=[ChatGeneration(message=answer)])


class PreviewRuns:
    def __init__(self):
        self.threads = {}
        self.runs = {}
        self.tasks = set()
        self.graph = create_agent(PreviewModel(responses=[]), tools=[ask_clarification_tool], middleware=[ClarificationMiddleware()], checkpointer=InMemorySaver())

    def bound(self, owner):
        host = self

        class Bound:
            def for_plugin(self, namespace):
                return self

            def check(self, thread_id):
                if host.threads.get(thread_id, {}).get("owner") != owner:
                    raise AgentRunError(404, "Thread unavailable")

            async def create_thread(self, *, assistant_id, thread_id, metadata):
                if thread_id in host.threads:
                    self.check(thread_id)
                host.threads.setdefault(thread_id, {"owner": owner, "assistant_id": assistant_id})
                return thread_id

            async def get_state(self, *, thread_id):
                self.check(thread_id)
                state = await host.graph.aget_state({"configurable": {"thread_id": thread_id}})
                if not state.values:
                    raise AgentRunError(404, "No checkpoint")
                return {"values": {"messages": [m.model_dump() for m in state.values["messages"]]}, "next": list(state.next)}

            async def start(self, *, thread_id, input, idempotency_key):
                self.check(thread_id)
                if idempotency_key in host.runs:
                    return host.runs[idempotency_key]
                if any(r.thread_id == thread_id and r.status == "running" for r in host.runs.values()):
                    raise AgentRunError(409, "Busy")
                run = AgentRun(thread_id, idempotency_key, "running", host.threads[thread_id]["assistant_id"])
                host.runs[idempotency_key] = run

                async def execute():
                    await host.graph.ainvoke(input, config={"configurable": {"thread_id": thread_id}})
                    host.runs[idempotency_key] = AgentRun(thread_id, idempotency_key, "success", run.assistant_id)

                task = asyncio.create_task(execute())
                host.tasks.add(task)
                task.add_done_callback(host.tasks.discard)
                return run

            async def get(self, *, thread_id, run_id):
                self.check(thread_id)
                return host.runs[run_id]

        return Bound()


def create_app(directory):
    sys.path.insert(0, str(Path(__file__).resolve().parents[2] / "examples/deerflow-extension-agent-teams"))
    extensions, diagnostics = load_extensions([ExtensionSpec(use="deerflow_extension_agent_teams:install", config={"enabled": True, "storage_path": str(Path(directory) / "teams.sqlite")}, required=True)])
    assert not diagnostics
    ((_, plugin),) = extensions.plugins
    service = plugin.backend[0].handler.__self__
    runs = PreviewRuns()

    @asynccontextmanager
    async def lifespan(app):
        await service.start(None)
        yield
        await service.stop()
        await asyncio.gather(*runs.tasks, return_exceptions=True)

    app = FastAPI(lifespan=lifespan)
    app.state.extensions = extensions

    @app.middleware("http")
    async def identity(request, call_next):
        request.state.user = SimpleNamespace(id=request.headers.get("x-test-user", "alice"), system_role="user")
        request.state.auth_source = "session"
        return await call_next(request)

    setattr(app.state, EXTENSION_PRINCIPAL_RESOLVER_KEY, lambda request: ExtensionPrincipal(request.state.user.id))
    setattr(app.state, AGENT_RUNS_RESOLVER_KEY, lambda request: runs.bound(request.state.user.id))
    app.include_router(router)

    @app.post("/preview/peer-request")
    async def peer_request(payload: dict, request: Request):
        owner = request.state.user.id
        return await service.send(
            {"team_id": payload["team_id"], "member_id": payload["member_id"], "text": payload["text"], "request_id": "browser-peer"},
            ToolContext(ExtensionPrincipal(owner), {"enabled": True}, payload["source_thread"], agent_runs=runs.bound(owner)),
        )

    @app.get("/api/agents")
    async def catalog():
        return {
            "agents": [
                {"name": "researcher", "display_name": "Research", "description": "Find and check source evidence"},
                {"name": "reviewer", "display_name": "Review", "description": "Independent quality review"},
                {"name": "writer", "display_name": "Writer", "description": "Write clear reports"},
            ]
        }

    @app.get("/", response_class=HTMLResponse)
    async def preview():
        return """<!doctype html><html lang="en"><meta charset="utf-8"><title>Agent teams preview</title>
<meta name="viewport" content="width=device-width,initial-scale=1">
<style>:root{--destructive:oklch(0.577 0.245 27.325)}
body{font:14px system-ui;background:#faf9f3;color:#252722;margin:0}
nav{height:56px;border-bottom:1px solid #e5e5de;padding:0 32px;display:flex;align-items:center;color:#777a72;font-size:12px}
main{max-width:1152px;margin:auto;padding:32px 40px;box-sizing:border-box}
h1{font-size:24px;font-weight:600;margin:0 0 24px}
@media(max-width:720px){main{padding:24px 20px}}
html.dark{--card:#24251f;--foreground:#eeeee8;--muted-foreground:#a2a49a;--border:#414239;--muted:#303128;--primary:#dbe4d6;--primary-foreground:#242d22;--destructive:oklch(0.704 0.191 22.216)}
html.dark body{background:#1c1d18;color:#eeeee8}</style>
<nav>Workspace　/　Agent teams</nav><main><h1>Agent teams</h1><div id="root"></div></main>
<script type="module">
const descriptors = await (await fetch('/api/plugins')).json();
const descriptor = descriptors.find(p => p.namespace === 'community.agent-teams');
const {default: plugin} = await import(descriptor.entry);
const context = {namespace: descriptor.namespace, locale: new URLSearchParams(location.search).get('locale') || 'en', settings: descriptor.settings,
signal: new AbortController().signal, openConversation: async id => {window.openedThread = id},
async callBackend(action,payload){
const response = await fetch(`/api/plugins/${descriptor.namespace}/actions/${action}`, {method:'POST',headers:{'Content-Type':'application/json','X-Deerflow-Plugin-Viewer':descriptor.viewer_id},body:JSON.stringify(payload)});
const result = await response.json(); if(!response.ok) throw new Error(result.detail); return result; }};
window.teamPlugin = plugin; window.teamContext = context;
const root = document.querySelector('#root').attachShadow({mode:'open'});
window.teamView = plugin.surfaces[0].mount(root, context);
</script></html>"""

    return app


if __name__ == "__main__":
    with TemporaryDirectory(prefix="deerflow-teams-preview-") as directory:
        uvicorn.run(create_app(directory), host="127.0.0.1", port=int(sys.argv[1]), log_level="warning")

"""Tests for build_principal_from_context — the single Principal builder.

This builder is the only sanctioned way to construct a Principal from runtime
context. Both Layer 1 (tool assembly) and Layer 2 (GuardrailAuthorizationAdapter)
must use it so identity semantics stay consistent.
"""

from __future__ import annotations

import pytest

from deerflow.authz.principal import build_principal_from_context


class TestPrincipalBuilderFields:
    """Verify all 7 Principal fields are explicitly constructed."""

    def test_empty_context(self):
        p = build_principal_from_context({}, default_role="user")
        assert p.user_id is None
        assert p.role == "user"
        assert p.oauth_provider is None
        assert p.oauth_id is None
        assert p.channel_user_id is None
        assert p.is_internal is False
        assert p.attributes == {}

    def test_full_field_mapping(self):
        context = {
            "user_id": "u1",
            "user_role": "admin",
            "oauth_provider": "github",
            "oauth_id": "gh-123",
            "channel_user_id": "ou_sender_1",
            "is_internal": True,
            "authz_attributes": {"department": "eng"},
        }
        p = build_principal_from_context(context, default_role="user")
        assert p.user_id == "u1"
        assert p.role == "admin"
        assert p.oauth_provider == "github"
        assert p.oauth_id == "gh-123"
        assert p.channel_user_id == "ou_sender_1"
        assert p.is_internal is True
        assert p.attributes == {"department": "eng"}

    def test_partial_context(self):
        context = {"user_id": "u1", "user_role": "user"}
        p = build_principal_from_context(context, default_role="admin")
        assert p.user_id == "u1"
        assert p.role == "user"
        assert p.oauth_provider is None
        assert p.oauth_id is None


class TestRoleResolution:
    """Role fallback rules."""

    def test_none_role_uses_default(self):
        p = build_principal_from_context({"user_role": None}, default_role="guest")
        assert p.role == "guest"

    def test_empty_string_role_uses_default(self):
        p = build_principal_from_context({"user_role": ""}, default_role="guest")
        assert p.role == "guest"

    def test_missing_role_uses_default(self):
        p = build_principal_from_context({}, default_role="guest")
        assert p.role == "guest"

    def test_unknown_role_preserved(self):
        """A non-empty but unknown role must NOT fall back to default_role."""
        p = build_principal_from_context({"user_role": "editor"}, default_role="user")
        assert p.role == "editor"


class TestIsInternalStrictBool:
    """is_internal must only be True when the value is strictly True."""

    @pytest.mark.parametrize(
        "value,expected",
        [
            (True, True),
            (False, False),
            (1, False),
            ("true", False),
            ("1", False),
            (None, False),
            ([], False),
            ({}, False),
        ],
    )
    def test_is_internal_strict_bool(self, value, expected):
        p = build_principal_from_context({"is_internal": value}, default_role="user")
        assert p.is_internal is expected


class TestAttributes:
    """Attributes copy and validation semantics."""

    def test_missing_attributes(self):
        p = build_principal_from_context({}, default_role="user")
        assert p.attributes == {}

    def test_none_attributes(self):
        p = build_principal_from_context({"authz_attributes": None}, default_role="user")
        assert p.attributes == {}

    def test_mapping_attributes_copied(self):
        attrs = {"team": "platform"}
        p = build_principal_from_context({"authz_attributes": attrs}, default_role="user")
        assert p.attributes == {"team": "platform"}
        # Mutating input after build must not affect Principal
        attrs["team"] = "changed"
        assert p.attributes["team"] == "platform"

    def test_empty_mapping_attributes(self):
        p = build_principal_from_context({"authz_attributes": {}}, default_role="user")
        assert p.attributes == {}

    @pytest.mark.parametrize(
        "invalid",
        [
            [("key", "value")],  # list of tuples (not a Mapping at runtime)
            "not a mapping",
            42,
            [1, 2, 3],
        ],
    )
    def test_non_mapping_attributes_raises_type_error(self, invalid):
        with pytest.raises(TypeError, match="authz_attributes must be a Mapping"):
            build_principal_from_context({"authz_attributes": invalid}, default_role="user")

    def test_type_error_includes_actual_type(self):
        with pytest.raises(TypeError, match="list"):
            build_principal_from_context({"authz_attributes": [1, 2]}, default_role="user")


class TestPureFunction:
    """Builder must not modify its input."""

    def test_input_not_modified(self):
        context = {"user_id": "u1", "user_role": "admin", "authz_attributes": {"k": "v"}}
        original = dict(context)
        build_principal_from_context(context, default_role="user")
        assert context == original

"""Tests for the authorization provider protocol, adapter, and configuration.

Phase 0 covers scaffolding only (no behavior change at ``enabled: false``).
These tests verify:
- Protocol conformance and ``@runtime_checkable`` isinstance checks.
- Principal / AuthzRequest / AuthzDecision dataclass construction.
- GuardrailAuthorizationAdapter request mapping and decision conversion.
- AuthorizationConfig defaults, singleton load/reset, and AppConfig wiring.
"""

from __future__ import annotations

import asyncio

import pytest

from deerflow.authz.adapter import GuardrailAuthorizationAdapter
from deerflow.authz.provider import (
    AuthorizationProvider,
    AuthzDecision,
    AuthzReason,
    AuthzRequest,
    Principal,
)
from deerflow.config.app_config import AppConfig
from deerflow.config.authorization_config import (
    AuthorizationConfig,
    get_authorization_config,
    load_authorization_config_from_dict,
    reset_authorization_config,
)
from deerflow.config.sandbox_config import SandboxConfig
from deerflow.guardrails.provider import GuardrailDecision, GuardrailProvider, GuardrailRequest

# --- Test providers ---


class _AllowAllProvider:
    """Provider that allows everything."""

    name = "allow-all"

    def authorize(self, request: AuthzRequest) -> AuthzDecision:
        return AuthzDecision(allow=True, reasons=[AuthzReason(code="test.allowed", message="allow-all")])

    async def aauthorize(self, request: AuthzRequest) -> AuthzDecision:
        return self.authorize(request)

    def filter_resources(self, principal: Principal, resource_type: str, candidates: list[str]) -> list[str]:
        return list(candidates)


class _DenyAllProvider:
    """Provider that denies everything."""

    name = "deny-all"

    def authorize(self, request: AuthzRequest) -> AuthzDecision:
        return AuthzDecision(allow=False, reasons=[AuthzReason(code="test.denied", message="deny-all")], policy_id="test.deny.v1")

    async def aauthorize(self, request: AuthzRequest) -> AuthzDecision:
        return self.authorize(request)

    def filter_resources(self, principal: Principal, resource_type: str, candidates: list[str]) -> list[str]:
        return []


class _FilterByDenylistProvider:
    """Provider whose filter_resources removes a denylist, regardless of authorize()."""

    name = "denylist-filter"

    def __init__(self, *, denied: list[str] | None = None):
        self._denied = set(denied) if denied else set()

    def authorize(self, request: AuthzRequest) -> AuthzDecision:
        if request.target in self._denied:
            return AuthzDecision(allow=False, reasons=[AuthzReason(code="test.denied", message=f"'{request.target}' is denied")])
        return AuthzDecision(allow=True, reasons=[AuthzReason(code="test.allowed")])

    async def aauthorize(self, request: AuthzRequest) -> AuthzDecision:
        return self.authorize(request)

    def filter_resources(self, principal: Principal, resource_type: str, candidates: list[str]) -> list[str]:
        return [c for c in candidates if c not in self._denied]


# --- Protocol conformance ---


class TestProtocolConformance:
    """Verify the @runtime_checkable Protocol recognizes concrete providers."""

    def test_allow_all_is_authorization_provider(self):
        assert isinstance(_AllowAllProvider(), AuthorizationProvider)

    def test_deny_all_is_authorization_provider(self):
        assert isinstance(_DenyAllProvider(), AuthorizationProvider)

    def test_plain_object_without_methods_is_not_provider(self):
        class _NotAProvider:
            pass

        assert not isinstance(_NotAProvider(), AuthorizationProvider)

    def test_provider_without_filter_resources_is_not_provider(self):
        """filter_resources is a required Protocol method.

        A provider that only implements name/authorize/aauthorize but omits
        filter_resources must NOT pass isinstance — otherwise it would be
        silently accepted as an AuthorizationProvider and Layer 1 would
        get None (fail-open) when calling filter_resources.
        """

        class _NoFilterMethod:
            name = "no-filter"

            def authorize(self, request: AuthzRequest) -> AuthzDecision:
                return AuthzDecision(allow=True)

            async def aauthorize(self, request: AuthzRequest) -> AuthzDecision:
                return self.authorize(request)

        assert not isinstance(_NoFilterMethod(), AuthorizationProvider)


# --- Dataclass construction ---


class TestDataclasses:
    """Verify Principal / AuthzRequest / AuthzDecision construction."""

    def test_principal_defaults(self):
        p = Principal()
        assert p.user_id is None
        assert p.role is None
        assert p.oauth_provider is None
        assert p.oauth_id is None
        assert p.channel_user_id is None
        assert p.is_internal is False
        assert p.attributes == {}

    def test_principal_with_fields(self):
        p = Principal(user_id="u1", role="admin", oauth_provider="github", oauth_id="gh-123", is_internal=True)
        assert p.user_id == "u1"
        assert p.role == "admin"
        assert p.oauth_provider == "github"
        assert p.oauth_id == "gh-123"
        assert p.is_internal is True

    def test_authz_request(self):
        p = Principal(user_id="u1", role="user")
        req = AuthzRequest(principal=p, resource="tool", action="call", target="bash")
        assert req.principal.user_id == "u1"
        assert req.resource == "tool"
        assert req.action == "call"
        assert req.target == "bash"
        assert req.context == {}

    def test_authz_request_with_context(self):
        p = Principal(user_id="u1")
        req = AuthzRequest(principal=p, resource="tool", action="call", target="write_file", context={"thread_id": "t1"})
        assert req.context["thread_id"] == "t1"

    def test_authz_decision_defaults(self):
        d = AuthzDecision(allow=True)
        assert d.allow is True
        assert d.reasons == []
        assert d.policy_id is None
        assert d.metadata == {}

    def test_authz_decision_with_reasons(self):
        d = AuthzDecision(allow=False, reasons=[AuthzReason(code="denied", message="no access")], policy_id="p1")
        assert d.allow is False
        assert len(d.reasons) == 1
        assert d.reasons[0].code == "denied"
        assert d.reasons[0].message == "no access"
        assert d.policy_id == "p1"


# --- filter_resources ---


class TestFilterResources:
    """Verify the Layer 1 batch filter."""

    def test_allow_all_returns_all(self):
        provider = _AllowAllProvider()
        result = provider.filter_resources(Principal(role="user"), "tool", ["bash", "web_search", "read_file"])
        assert result == ["bash", "web_search", "read_file"]

    def test_deny_all_returns_empty(self):
        provider = _DenyAllProvider()
        result = provider.filter_resources(Principal(role="user"), "tool", ["bash", "web_search"])
        assert result == []

    def test_denylist_filter_removes_denied(self):
        provider = _FilterByDenylistProvider(denied=["bash", "write_file"])
        result = provider.filter_resources(Principal(role="user"), "tool", ["bash", "web_search", "write_file", "read_file"])
        assert result == ["web_search", "read_file"]


# --- GuardrailAuthorizationAdapter ---


def _make_guardrail_request(
    *,
    tool_name: str = "bash",
    tool_input: dict | None = None,
    user_id: str | None = "u1",
    user_role: str | None = "user",
    oauth_provider: str | None = None,
    oauth_id: str | None = None,
    channel_user_id: str | None = None,
    thread_id: str | None = "t1",
    is_subagent: bool = False,
    agent_id: str | None = None,
    timestamp: str = "",
    is_internal: bool = False,
    authz_attributes: dict | None = None,
) -> GuardrailRequest:
    return GuardrailRequest(
        tool_name=tool_name,
        tool_input=tool_input or {},
        user_id=user_id,
        user_role=user_role,
        oauth_provider=oauth_provider,
        oauth_id=oauth_id,
        channel_user_id=channel_user_id,
        thread_id=thread_id,
        is_subagent=is_subagent,
        agent_id=agent_id,
        timestamp=timestamp,
        is_internal=is_internal,
        authz_attributes=authz_attributes if authz_attributes is not None else {},
    )


class TestGuardrailAuthorizationAdapter:
    """Verify the adapter maps between Guardrail and Authz request/decision types."""

    def test_adapter_name(self):
        adapter = GuardrailAuthorizationAdapter(_AllowAllProvider())
        assert adapter.name == "authorization"

    def test_adapter_is_guardrail_provider(self):
        """The adapter must satisfy the GuardrailProvider Protocol so existing
        GuardrailMiddleware can enforce authz decisions without a new middleware."""
        adapter = GuardrailAuthorizationAdapter(_AllowAllProvider())
        assert isinstance(adapter, GuardrailProvider)

    def test_evaluate_allow(self):
        adapter = GuardrailAuthorizationAdapter(_AllowAllProvider())
        gr_req = _make_guardrail_request(tool_name="web_search")
        decision = adapter.evaluate(gr_req)
        assert decision.allow is True
        assert len(decision.reasons) == 1
        assert decision.reasons[0].code == "test.allowed"

    def test_evaluate_deny(self):
        adapter = GuardrailAuthorizationAdapter(_DenyAllProvider())
        gr_req = _make_guardrail_request(tool_name="bash")
        decision = adapter.evaluate(gr_req)
        assert decision.allow is False
        assert decision.policy_id == "test.deny.v1"

    def test_evaluate_maps_complete_principal_identity(self):
        """Every GuardrailRequest identity field flows into Principal."""
        captured: list[AuthzRequest] = []

        class _CapturingProvider:
            name = "capturing"

            def authorize(self, request: AuthzRequest) -> AuthzDecision:
                captured.append(request)
                return AuthzDecision(allow=True, reasons=[AuthzReason(code="ok")])

            async def aauthorize(self, request: AuthzRequest) -> AuthzDecision:
                return self.authorize(request)

            def filter_resources(self, principal: Principal, resource_type: str, candidates: list[str]) -> list[str]:
                return list(candidates)

        adapter = GuardrailAuthorizationAdapter(_CapturingProvider())
        gr_req = _make_guardrail_request(
            user_id="user-42",
            user_role="admin",
            oauth_provider="github",
            oauth_id="gh-42",
            channel_user_id="channel-42",
            is_internal=True,
            authz_attributes={"department": "engineering"},
            tool_name="write_file",
        )
        adapter.evaluate(gr_req)

        assert len(captured) == 1
        authz_req = captured[0]
        assert authz_req.principal.user_id == "user-42"
        assert authz_req.principal.role == "admin"
        assert authz_req.principal.oauth_provider == "github"
        assert authz_req.principal.oauth_id == "gh-42"
        assert authz_req.principal.channel_user_id == "channel-42"
        assert authz_req.principal.is_internal is True
        assert authz_req.principal.attributes == {"department": "engineering"}
        assert authz_req.resource == "tool"
        assert authz_req.action == "call"
        assert authz_req.target == "write_file"

    def test_evaluate_maps_is_internal_true(self):
        """is_internal=True on GuardrailRequest maps to Principal.is_internal=True."""
        captured: list[AuthzRequest] = []

        class _CapturingProvider:
            name = "capturing"

            def authorize(self, request: AuthzRequest) -> AuthzDecision:
                captured.append(request)
                return AuthzDecision(allow=True)

            async def aauthorize(self, request: AuthzRequest) -> AuthzDecision:
                return self.authorize(request)

            def filter_resources(self, principal: Principal, resource_type: str, candidates: list[str]) -> list[str]:
                return list(candidates)

        adapter = GuardrailAuthorizationAdapter(_CapturingProvider())
        gr_req = _make_guardrail_request(user_role="user", is_internal=True)
        adapter.evaluate(gr_req)
        assert captured[0].principal.is_internal is True

    def test_evaluate_maps_is_internal_false(self):
        """is_internal=False (default) maps to Principal.is_internal=False."""
        captured: list[AuthzRequest] = []

        class _CapturingProvider:
            name = "capturing"

